import requests import os
TOKEN=os.environ.get('TOKEN') robot_user = "fed-test+robot1"
def get_quay_robot_token(fed_token): URL = "https://<quay-server.example.com>/oauth2/federation/robot/token" response = requests.get(URL, auth=(robot_user,fed_token)) print(response) print(response.text)
if __name__ == "__main__": get_quay_robot_token(TOKEN)
